var e=JSON.parse(`[{"year":2021,"paper":"GS1","question":1,"q":"With reference to the history of ancient India, Bhavabhuti, Hastimalla and Kshemeshvara were famous:","options":["Jain monks","playwrights","temple architects","philosophers"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 2:</b> <b>Bhavabhuti</b> (author of <i>Malatimadhava</i>, <i>Mahaviracharita</i>, and <i>Uttararamacharita</i>), <b>Hastimalla</b> (noted 13th-century Hoysala Jain Sanskrit playwright who composed <i>Vikrantakaurava</i>), and <b>Kshemeshvara</b> (10th-century dramatist who wrote <i>Chanda-kaushika</i>) were celebrated Sanskrit <b>playwrights</b> (dramatists).</p></div> }}"},{"year":2021,"paper":"GS1","question":2,"q":"Consider the following statements:\\n1. The Montagu-Chelmsford Reforms of 1919 recommended granting voting rights to all the women above the age of 21.\\n2. The Government of India Act of 1935 gave women reserved seats in legislature.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statement 2 is correct:</b> The Government of India Act, 1935 extended the franchise and introduced separate electorates with reserved seats for women in federal and provincial legislatures.</p><p><b>Statement 1 is incorrect:</b> The Montagu-Chelmsford Reforms (1919) did not directly grant universal female suffrage above age 21; rather, it left the question of women's enfranchisement to the discretion of individual provincial legislative councils.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":3,"q":"With reference to 8th August, 1942 in Indian history, which one of the following statements is correct?","options":["The Quit India Resolution was adopted by the AICC.","The Viceroy's Executive Council was expanded to include more Indians.","The Congress ministries resigned in seven provinces.","Cripps proposed an Indian Union with full Dominion Status once the Second World War was over."],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> On <b>8th August, 1942</b>, the All India Congress Committee (AICC) met at the Gowalia Tank Maidan in Bombay and ratified the historic <b>Quit India Resolution</b>, following which Mahatma Gandhi gave the call to <i>'Do or Die'</i>.</p></div> }}"},{"year":2021,"paper":"GS1","question":4,"q":"Who among the following is associated with 'Songs from Prison', a translation of ancient Indian religious lyrics in English?","options":["Bal Gangadhar Tilak","Jawaharlal Nehru","Mohandas Karamchand Gandhi","Sarojini Naidu"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 3:</b> <b>Mohandas Karamchand Gandhi</b> translated ancient Indian devotional hymns and Upanishadic verses into English under the title <i>'Songs from Prison'</i> while incarcerated in the Yerwada Central Jail, Pune, in 1930.</p></div> }}"},{"year":2021,"paper":"GS1","question":5,"q":"With reference to medieval India, which one of the following is the correct sequence in ascending order in terms of size?","options":["Paragana &rightarrow; Sarkar &rightarrow; Suba","Sarkar &rightarrow; Paragana &rightarrow; Suba","Suba &rightarrow; Sarkar &rightarrow; Paragana","Paragana &rightarrow; Suba &rightarrow; Sarkar"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> In the Mughal administrative hierarchy, the spatial units organized in ascending order (smallest to largest) were: <b>Paragana</b> (group of villages) &rightarrow; <b>Sarkar</b> (district level) &rightarrow; <b>Suba</b> (province governed by a Subahdar).</p></div> }}"},{"year":2021,"paper":"GS1","question":6,"q":"Who among the following was associated as Secretary with Hindu Female School which later came to be known as Bethune Female School?","options":["Annie Besant","Debendranath Tagore","Ishwar Chandra Vidyasagar","Sarojini Naidu"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 3:</b> <b>Ishwar Chandra Vidyasagar</b> was intimately associated as the Secretary with the Hindu Female School (founded in Calcutta in 1849 by J.E.D. Bethune), which played a pioneering role in women's modern education in India.</p></div> }}"},{"year":2021,"paper":"GS1","question":7,"q":"In the context of Colonial India, Shah Nawaz Khan, Prem Kumar Sehgal and Gurbaksh Singh Dhillon are remembered as:","options":["leaders of Swadeshi and Boycott Movement","members of the Interim Government in 1946","members of the Drafting Committee in the Constituent Assembly","officers of the Indian National Army"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 4:</b> Colonel Prem Kumar Sehgal, Colonel Gurbaksh Singh Dhillon, and Major General Shah Nawaz Khan were prominent <b>officers of the Indian National Army (INA)</b> who faced the historic joint Red Fort treason trials in Delhi in 1945–46.</p></div> }}"},{"year":2021,"paper":"GS1","question":8,"q":"With reference to Indian history, which of the following statements is/are correct?\\n1. The Nizamat of Arcot emerged out of Hyderabad State.\\n2. The Mysore Kingdom emerged out of Vijayanagara Empire.\\n3. Rohilkhand Kingdom was formed out of the territories occupied by Ahmad Shah Durrani.\\n\\nSelect the correct answer using the code given below:","options":["1 and 2 only","2 only","2 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> The Carnatic/Arcot Nizamat was established as a subordinate dependency under the Nizam of Hyderabad before becoming autonomous. The Wodeyar Kingdom of Mysore emerged directly out of the disintegration of the Vijayanagara Empire after the battle of Talikota.</p><p><b>Statement 3 is incorrect:</b> Rohilkhand was carved out in the early 18th century by Ali Muhammad Khan taking advantage of the collapse of Mughal central authority, well before the invasions of Ahmad Shah Durrani.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":9,"q":"Which one of the following statements is correct?","options":["Ajanta Caves lie in the gorge of Waghora river.","Sanchi Stupa lies in the gorge of Chambal river.","Pandu-lena Cave Shrines lie in the gorge of Narmada river.","Amaravati Stupa lies in the gorge of Godavari river."],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The rock-cut <b>Ajanta Caves</b> are excavated into the semicircular cliff face of the picturesque crescent-shaped gorge formed by the <b>Waghora River</b> in Aurangabad district, Maharashtra.</p><p>Sanchi lies near the Betwa River (not Chambal); Pandavleni/Pandu-lena is near the Godavari River in Nashik (not Narmada); Amaravati Stupa is located on the Krishna River (not Godavari).</p></div> }}"},{"year":2021,"paper":"GS1","question":10,"q":"Consider the following statements:\\n1. 21st February is declared to be the International Mother Language Day by UNICEF.\\n2. The demand that Bangla has to be one of the national languages was raised in the Constituent Assembly of Pakistan.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statement 2 is correct:</b> On 23 February 1948, Dhirendranath Datta, a member from East Bengal, formally moved an amendment in the Constituent Assembly of Pakistan demanding that Bangla be recognized as one of the official state languages alongside Urdu.</p><p><b>Statement 1 is incorrect:</b> International Mother Language Day was proclaimed by the General Conference of <b>UNESCO</b> (not UNICEF) in November 1999.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":11,"q":"With reference to the 'Right to Privacy', under which Article of the Constitution of India is it protected as an intrinsic part of life and personal liberty?","options":["Article 14","Article 19","Article 21","Article 25"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 3:</b> The Supreme Court in the landmark nine-judge Constitution Bench ruling in <i>Justice K.S. Puttaswamy vs Union of India (2017)</i> affirmed that the Right to Privacy is a Fundamental Right protected under <b>Article 21</b> and Part III of the Constitution.</p></div> }}"},{"year":2021,"paper":"GS1","question":12,"q":"With reference to India, consider the following statements:\\n1. There is only one citizenship and one domicile.\\n2. A citizen by birth only can become the Head of State.\\n3. A foreigner once granted citizenship cannot be deprived of it under any circumstances.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","1 and 3","2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statement 1 is correct:</b> The Constitution establishes a single, uniform citizenship across the nation and recognizes a single domicile.</p><p><b>Statements 2 and 3 are incorrect:</b> In India, any citizen (whether by birth or naturalization) is eligible to become the President (Head of State), unlike in the US where only natural-born citizens can become President. A naturalized foreigner can be deprived of citizenship by the Central Government under Section 10 of the Citizenship Act, 1955 for fraud, false representation, or disloyalty to the Constitution.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":13,"q":"Which one of the following factors constitutes the best safeguard of liberty in a liberal democracy?","options":["A committed judiciary","Centralization of powers","Elected government","Separation of powers"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 4:</b> The <b>Separation of Powers</b> (as articulated by Montesquieu) among the Legislature, Executive, and Judiciary prevents the concentration and abuse of power, providing institutional checks and balances that serve as the strongest safeguard of individual liberty.</p></div> }}"},{"year":2021,"paper":"GS1","question":14,"q":"We adopted parliamentary democracy based on the British model, but how does our model differ from that model?\\n1. As regards legislation, the British Parliament is supreme or sovereign but in India, the power of the Parliament to legislate is limited.\\n2. In India, matters related to the constitutionality of the Amendment of an Act of the Parliament are referred to the Constitution Bench by the Supreme Court.\\n\\nSelect the correct answer using the code given below:","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Both statements 1 and 2 are correct:</b></p><ul><li><b>Statement 1:</b> The British Parliament operates under Parliamentary Sovereignty with no judicial review, whereas the Indian Parliament operates under Constitutional Supremacy where legislative powers are limited by Fundamental Rights, federal distribution of subjects, and the basic structure doctrine.</li><li><b>Statement 2:</b> Under Article 145(3), substantial questions of constitutional interpretation or the validity of constitutional amendments are heard by a Constitution Bench comprising a minimum of five Supreme Court judges.</li></ul><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":15,"q":"With reference to the 'New York Declaration on Forests', which of the following statements are correct?\\n1. It was first endorsed at the United Nations Climate Summit in 2014.\\n2. It endorses a global timeline to end the loss of forests.\\n3. It is a legally binding international declaration.\\n4. It is endorsed by governments, big companies and indigenous communities.\\n5. India was one of the signatories at its inception.\\n\\nSelect the correct answer using the code given below:","options":["1, 2 and 4","1, 3 and 5","3 and 4","2 and 5"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1, 2 and 4 are correct:</b> The New York Declaration on Forests (NYDF) was adopted at the 2014 UN Climate Summit as a non-binding, voluntary political declaration endorsed by governments, corporations, civil society, and indigenous groups pledging to halve deforestation by 2020 and end it by 2030.</p><p><b>Statements 3 and 5 are incorrect:</b> It is not legally binding, and India is not a signatory to the declaration.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":16,"q":"The 'R2 Code of Practices' constitutes a tool available for promoting the adoption of:","options":["environmentally responsible practices in electronics recycling industry","ecological management of 'Wetlands of International Importance' under the Ramsar Convention","sustainable practices in the cultivation of agricultural crops in degraded lands","Environmental Impact Assessment in the exploitation of natural resources"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The <b>Responsible Recycling (R2) Standard</b> (R2 Code of Practices), maintained by Sustainable Electronics Recycling International (SERI), is the global accredited standard establishing operational and environmental best practices for the <b>electronics recycling and refurbishment industry</b>.</p></div> }}"},{"year":2021,"paper":"GS1","question":17,"q":"Consider the following statements:\\nStatement 1: The United Nations Capital Development Fund (UNCDF) and the Arbor Day Foundation have recently recognized Hyderabad as 2020 Tree City of the World.\\nStatement 2: Hyderabad was selected for the recognition for a year following its commitment to grow and maintain the urban forests.\\n\\nWhich one of the following is correct in respect of the above statements?","options":["Both Statement 1 and Statement 2 are correct and Statement 2 is the correct explanation for Statement 1","Both Statement 1 and Statement 2 are correct but Statement 2 is not the correct explanation for Statement 1","Statement 1 is correct but Statement 2 is not correct","Statement 1 is not correct but Statement 2 is correct"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>Statement 1 is incorrect:</b> The 'Tree Cities of the World' program is run jointly by the <b>Food and Agriculture Organization (FAO)</b> and the Arbor Day Foundation (not UNCDF).</p><p><b>Statement 2 is correct:</b> Hyderabad was recognized as a Tree City of the World for its urban forestry initiative (Telangana Ku Haritha Haram) to grow and maintain urban tree cover.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":18,"q":"With reference to the 'Mitochondrial Replacement Therapy' (MRT), consider the following statements:\\n1. It is a form of reproductive technology aimed at preventing the transmission of mitochondrial diseases from mother to offspring.\\n2. It involves replacing mutated mitochondrial DNA (mtDNA) in an egg or embryo with healthy mtDNA from a female donor.\\n3. The resulting child inherits genetic material from three individuals.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> Mitochondrial Replacement Therapy (MRT / three-parent IVF) transfers nuclear DNA from intending parents into an enucleated donor egg containing healthy donor mitochondria, ensuring the child avoids maternal mitochondrial genetic disorders while carrying nuclear DNA from parents and mitochondrial DNA from the donor.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":19,"q":"Consider the following:\\n1. Bacteria\\n2. Fungi\\n3. Virus\\n\\nWhich of the above can be cultured in artificial/synthetic medium?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Bacteria (1) and Fungi (2) can be cultured in artificial media:</b> Bacteria and fungi are cellular organisms that metabolize and replicate in synthetic nutrient media (agar broths).</p><p><b>Viruses (3) cannot</b> be cultured on synthetic, cell-free media because they are obligate intracellular parasites requiring living host cells (tissue cultures or embryonated eggs) to replicate.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":20,"q":"The term 'ACE2' is talked about in the context of:","options":["genes introduced in the genetically modified plants","development of India's own satellite navigation system","radio collars for wildlife tracking","spread of viral diseases"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 4:</b> <b>Angiotensin-Converting Enzyme 2 (ACE2)</b> is a membrane-bound protein receptor on human respiratory and intestinal epithelial cells that acts as the primary cellular entry point for the spike protein of coronaviruses (such as SARS-CoV and SARS-CoV-2) during the <b>spread of viral diseases</b>.</p></div> }}"},{"year":2021,"paper":"GS1","question":21,"q":"Consider the following statements:\\n1. 'Right to the City' is an agreed human right under the UN-Habitat declarations.\\n2. 'Right to the City' gives the authorized occupant of a city the right to reclaim public spaces and public participation in the city.\\n3. 'Right to the City' means that the State cannot deny any public service or facility to the unauthorized colonies in the city.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","3 only","1 and 2","2 and 3"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> The 'Right to the City' was recognized in the UN-Habitat III New Urban Agenda (2016) as a collective paradigm giving inhabitants democratic rights to access, participate in urban planning, and reclaim inclusive public spaces.</p><p><b>Statement 3 is incorrect:</b> The concept does not create an absolute statutory bar preventing municipal bodies from regulating or denying infrastructure access to unauthorized settlements.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":22,"q":"With reference to the Indian economy, consider the following statements:\\n1. 'Money Multiplier' in an economy increases with which one of the following?\\n(a) Increase in the Cash Reserve Ratio\\n(b) Increase in the Statutory Liquidity Ratio\\n(c) Increase in the banking habit of the population\\n(d) Increase in the population of the country\\n\\nWhich one is the correct option?","options":["Increase in the Cash Reserve Ratio","Increase in the Statutory Liquidity Ratio","Increase in the banking habit of the population","Increase in the population of the country"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 3:</b> The <b>Money Multiplier</b> $(m = \\\\frac{1 + c}{c + r})$ increases when the currency-deposit ratio ($c$) declines—i.e., as people deposit more cash into commercial banks (increase in banking habits), enabling greater credit creation.</p><p>Increases in CRR or SLR lock up bank reserves, reducing the multiplier.</p></div> }}"},{"year":2021,"paper":"GS1","question":23,"q":"With reference to the 'Water Credit' initiative, consider the following statements:\\n1. It puts microfinance tools to work in the water and sanitation sector.\\n2. It is a global initiative launched under the aegis of the World Health Organization and the World Bank.\\n3. It aims to enable the poor people to meet their water needs without depending on subsidies.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 3 are correct:</b> WaterCredit is a market-driven initiative that provides small, affordable micro-loans to low-income households to install household water taps and toilets, building sustainable self-reliance without waiting for government subsidies.</p><p><b>Statement 2 is incorrect:</b> WaterCredit was pioneered by the non-profit organization <b>Water.org</b> (co-founded by Gary White and Matt Damon), not the WHO or World Bank.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":24,"q":"In India, the term 'Halbi, Ho and Kui' are related to:","options":["tribal languages","dance forms of Northwest India","musical instruments of South India","pre-historic cave paintings"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> <b>Halbi</b> (Indo-Aryan tribal tongue spoken in Bastar), <b>Ho</b> (Munda/Austroasiatic language spoken in Jharkhand/Odisha), and <b>Kui</b> (Dravidian tribal language spoken by the Kandha tribe of Odisha) are <b>tribal languages</b>.</p></div> }}"},{"year":2021,"paper":"GS1","question":25,"q":"Consider the following statements regarding the 'Indian National Movement':\\n1. The Illbert Bill controversy was related to the removal of disqualifications imposed on Indian magistrates with regard to the trial of Europeans.\\n2. Lord Ripon was the Viceroy when the Illbert Bill was introduced.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Both statements 1 and 2 are correct:</b> The Ilbert Bill (1883), drafted under Viceroy Lord Ripon's administration by Law Member Sir C.P. Ilbert, proposed granting Indian district magistrates and sessions judges the power to try European British subjects in criminal cases, triggering intense racial opposition from the Anglo-Indian community.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":26,"q":"With reference to the history of ancient India, consider the following pairs:\\n\\n{{ <table class='table table-bordered text-center' style='width:100%; border: 1px solid #dee2e6;'><thead><tr style='background-color:#f8f9fa;'><th>Ancient City</th><th>State / Region</th></tr></thead><tbody><tr><td>1. Burzahom</td><td>Jammu & Kashmir</td></tr><tr><td>2. Chandraketugarh</td><td>West Bengal</td></tr><tr><td>3. Inamgaon</td><td>Maharashtra</td></tr></tbody></table> }}\\n\\nWhich of the pairs given above are correctly matched?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three pairs are correctly matched:</b></p><ul><li><b>Burzahom:</b> Neolithic site in Jammu & Kashmir known for pit-dwellings.</li><li><b>Chandraketugarh:</b> Ancient riverine/port city in West Bengal noted for terracotta craft.</li><li><b>Inamgaon:</b> Major Chalcolithic settlement in Maharashtra.</li></ul><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":27,"q":"Which one of the following is used in preparing a natural mosquito repellent?","options":["Congress grass","Elephant grass","Lemongrass","Nut grass"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 3:</b> <b>Lemongrass</b> (<i>Cymbopogon</i>) contains essential oils such as citronella, which is widely utilized as a natural botanical mosquito and insect repellent.</p></div> }}"},{"year":2021,"paper":"GS1","question":28,"q":"Consider the following kinds of organisms:\\n1. Copepods\\n2. Cyanobacteria\\n3. Diatoms\\n4. Foraminifera\\n\\nWhich of the above are primary producers in the food chains of oceans?","options":["1 and 2","2 and 3","3 and 4","1 and 4"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Cyanobacteria (2) and Diatoms (3) are primary producers:</b> They are photosynthetic autotrophs that form the foundational base of marine food webs.</p><p>Copepods and Foraminifera are heterotrophic zooplankton/consumers.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":29,"q":"Consider the following animals:\\n1. Hedgehog\\n2. Marmot\\n3. Pangolin\\n\\nTo reduce the chance of being captured by predators, which of the above organisms rolls up/roll up and protects/protect its/their vulnerable parts?","options":["1 and 2","2 only","3 only","1 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>Hedgehogs (1) and Pangolins (3) roll into a defensive ball:</b> Hedgehogs expose their spines and pangolins cover their soft underside with overlapping keratin scales to deter predators.</p><p>Marmots are large ground squirrels that flee into burrows rather than curling into a defensive ball.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":30,"q":"With reference to the 'New Development Bank' (NDB), consider the following statements:\\n1. It was established by the BRICS countries at the 2014 Fortaleza Summit.\\n2. The headquarters of the NDB is located in Shanghai, China.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Both statements 1 and 2 are correct:</b> The New Development Bank (NDB) was formally established by the BRICS nations (Brazil, Russia, India, China, South Africa) during the 6th BRICS Summit in Fortaleza in 2014, and its global headquarters is situated in Shanghai, China.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":31,"q":"Consider the following statements regarding the 'Indian Ocean Rim Association' (IORA):\\n1. It was established in 1997 to promote sustainable growth and balanced development within the Indian Ocean region.\\n2. Its Secretariat is located in Ebene, Mauritius.\\n3. All littoral states of the Indian Ocean are automatically permanent members of IORA.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> IORA is a regional tripartite forum formed in 1997, hosted by the Secretariat in Mauritius.</p><p><b>Statement 3 is incorrect:</b> Membership is based on accession and consensus, not automatic for all littoral states (e.g., Pakistan is not a member).</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":32,"q":"With reference to 'Street Lighting National Programme' (SLNP) in India, consider the following statements:\\n1. It is implemented by Energy Efficiency Services Limited (EESL).\\n2. It aims to replace conventional street lights with energy-efficient LED lights.\\n3. The entire capital cost is borne directly by local municipal bodies upfront.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> SLNP is managed by EESL to convert conventional street lights to smart LEDs.</p><p><b>Statement 3 is incorrect:</b> EESL uses a Pay-As-You-Save (PAYS) model where EESL bears the entire upfront capital investment, which is repaid by municipalities from energy savings over time.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":33,"q":"Consider the following statements regarding 'Magnetite' particles suspected to cause neurodegenerative problems:\\n1. They can be generated from the brake systems of motor vehicles.\\n2. They are produced from the combustion engines of motor vehicles.\\n3. They can be generated from power plants using fossil fuels.\\n4. Microwave ovens in homes are a major source of airborne magnetite nanoparticles.\\n\\nWhich of the statements given above are correct?","options":["1, 2 and 3 only","1, 2 and 4 only","3 and 4 only","1, 2, 3 and 4"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1, 2 and 3 are correct:</b> Airborne magnetite ($Fe_3O_4$) nanoparticles arise from vehicular brake wear, engine exhaust combustion, and industrial/coal-fired power plant emissions.</p><p><b>Statement 4 is incorrect:</b> Sealed domestic microwave ovens do not emit airborne magnetic particulates into ambient air.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":34,"q":"Which one of the following is a filter feeder?","options":["Catfish","Octopus","Oyster","Pelican"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 3:</b> <b>Oysters</b> are bivalve mollusks that feed by pumping surrounding seawater through their gills, filtering out suspended phytoplankton, algae, and organic particles.</p></div> }}"},{"year":2021,"paper":"GS1","question":35,"q":"In case of which one of the following biogeochemical cycles, the weathering of rocks is the main source of release of nutrient to enter the cycle?","options":["Carbon cycle","Nitrogen cycle","Phosphorus cycle","Sulphur cycle"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 3:</b> Unlike gaseous cycles (carbon and nitrogen) which rely on atmospheric reservoirs, the <b>Phosphorus cycle</b> is a classic sedimentary cycle where chemical weathering of phosphate-bearing rocks releases inorganic phosphate ions into soil and water.</p></div> }}"},{"year":2021,"paper":"GS1","question":36,"q":"Which of the following are detritivores?\\n1. Earthworms\\n2. Jellyfish\\n3. Millipedes\\n4. Seahorses\\n5. Woodlice\\n\\nSelect the correct answer using the code given below:","options":["1, 2 and 4 only","2, 3, 4 and 5 only","1, 3 and 5 only","1, 2, 3, 4 and 5"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Earthworms (1), Millipedes (3), and Woodlice (5) are detritivores:</b> They consume decomposing organic matter, plant litter, and detritus.</p><p>Jellyfish and Seahorses are carnivorous predators that feed on live plankton and small fish.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":37,"q":"The 'Common Carbon Metric', supported by UNEP, has been developed for:","options":["assessing the carbon footprint of building operations around the world","enabling commercial farming entities to enter carbon emission trading","enabling governments to assess overall carbon footprint caused by their countries","assessing the overall carbon footprint caused by the use of fossil fuels by the world in a unit time"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The <b>Common Carbon Metric</b> was developed by UNEP's Sustainable Buildings and Climate Initiative (UNEP-SBCI) to establish a global standard protocol for measuring greenhouse gas emissions and energy use from <b>building operations</b>.</p></div> }}"},{"year":2021,"paper":"GS1","question":38,"q":"Which of the following have species that can establish symbiotic relationship with other organisms?\\n1. Cnidarians\\n2. Fungi\\n3. Protozoa\\n\\nSelect the correct answer using the code given below:","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three groups form symbiotic associations:</b></p><ul><li><b>Cnidarians:</b> Corals and sea anemones partner with photosynthetic zooxanthellae.</li><li><b>Fungi:</b> Form lichens (with algae/cyanobacteria) and mycorrhizae (with plant roots).</li><li><b>Protozoa:</b> Symbionts like trichonympha reside in termite guts to digest cellulose.</li></ul><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":39,"q":"With reference to the 'Indian Sovereign Wealth Fund' known as the National Investment and Infrastructure Fund (NIIF), consider the following statements:\\n1. It is a category II Alternative Investment Fund registered with SEBI.\\n2. The Government of India holds 100% equity in NIIF.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statement 1 is correct:</b> NIIF is registered with SEBI as a Category II Alternative Investment Fund (AIF) to attract commercial and sovereign investments into Indian infrastructure.</p><p><b>Statement 2 is incorrect:</b> The Government of India holds <b>49%</b> of the equity in NIIF, while the remaining 51% is held by domestic and foreign institutional investors.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":40,"q":"Consider the following statements regarding the 'P-8I' aircraft often in the news:\\n1. It is a long-range maritime reconnaissance and anti-submarine warfare aircraft.\\n2. It is manufactured by Boeing for the Indian Navy.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Both statements 1 and 2 are correct:</b> The Boeing P-8I Poseidon is a customized maritime patrol and anti-submarine warfare (ASW) aircraft operated by the Indian Navy for surveillance across the Indian Ocean Region.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":41,"q":"With reference to the 'Triclosan', considered harmful when exposed to high levels for a long time, it is most likely present in which of the following?","options":["Food preservatives","Fruit-ripening substances","Reused plastic containers","Toiletries"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 4:</b> <b>Triclosan</b> is a synthetic antibacterial and antifungal agent added to personal care products and <b>toiletries</b> (such as antibacterial soaps, toothpastes, and body washes).</p></div> }}"},{"year":2021,"paper":"GS1","question":42,"q":"Which one of the following is a reason why astronomical distances are measured in light-years?","options":["Distances among stellar bodies do not change.","Gravity of stellar bodies does not change.","Light always travels in straight lines.","Speed of light is always very constant."],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 4:</b> The <b>speed of light is constant</b> throughout the vacuum of space ($c \\\\approx 3 \\\\times 10^8\\\\text{ m/s}$), providing an invariant physical benchmark for measuring vast cosmic distances.</p></div> }}"},{"year":2021,"paper":"GS1","question":43,"q":"With reference to the 'Chinkiang vinegar' and other traditional fermented vinegars, the production involves the fermentation of ethanol into acetic acid by which class of organisms?","options":["Acetobacter bacteria","Cyanobacteria","Lactobacillus bacteria","Protozoa"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> Vinegar fermentation is carried out by acetic acid bacteria belonging to the genus <b>Acetobacter</b>, which aerobically oxidize ethanol into acetic acid.</p></div> }}"},{"year":2021,"paper":"GS1","question":44,"q":"Consider the following statements regarding the 'Indian Regional Navigation Satellite System' (NavIC):\\n1. It consists of a constellation of 7 operational satellites.\\n2. It covers the entire globe with full real-time positioning coverage.\\n3. It provides standard positioning service to civilian users and restricted service to authorized users.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 3 are correct:</b> NavIC is a 7-satellite constellation providing Standard Positioning Service (SPS) and encrypted Restricted Service (RS).</p><p><b>Statement 2 is incorrect:</b> NavIC is a <i>regional</i> system covering India and an area extending up to 1,500 km beyond its borders, not a global navigation system like GPS or Galileo.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":45,"q":"With reference to the 'Pradhan Mantri Fasal Bima Yojana', consider the following statements:\\n1. It provides comprehensive insurance cover against loss of crops from pre-sowing to post-harvest stages.\\n2. The use of technology like satellite imagery and drones is encouraged for quick settlement of claims.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Both statements 1 and 2 are correct:</b> PMFBY covers non-preventable yield risks from pre-sowing to post-harvest losses and integrates remote sensing, drone surveys, and the CROPIC app for rapid crop yield loss estimation.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":46,"q":"Consider the following statements regarding the 'Indo-Pacific Oceans Initiative' (IPOI):\\n1. It was launched by the Prime Minister of India at the 14th East Asia Summit in 2019.\\n2. It focuses on maritime security, marine ecology, and disaster risk reduction.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Both statements 1 and 2 are correct:</b> The IPOI was proposed by India at the East Asia Summit in Bangkok (2019) with seven collaborative pillars including Maritime Security, Marine Ecology, Disaster Risk Management, and Trade Connectivity.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":47,"q":"Consider the following statements regarding the 'Great Indian Hornbill':\\n1. It is listed as Vulnerable on the IUCN Red List.\\n2. In India, it is found in the Western Ghats and the forests of the Northeast.\\n3. The Hornbill Festival celebrated in Nagaland is named after this bird.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> The Great Indian Hornbill (<i>Buceros bicornis</i>) is listed as Vulnerable, inhabits canopy forests in the Western Ghats and Northeast India, and is celebrated in the cultural Hornbill Festival of Nagaland.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":48,"q":"With reference to the 'Global Innovation Index' (GII), it is released annually by which of the following organizations?","options":["World Economic Forum","World Intellectual Property Organization (WIPO)","World Bank","International Monetary Fund"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 2:</b> The <b>Global Innovation Index (GII)</b> is published annually by the <b>World Intellectual Property Organization (WIPO)</b> to benchmark the innovation performance of economies.</p></div> }}"},{"year":2021,"paper":"GS1","question":49,"q":"Consider the following statements regarding 'Bioluminescence':\\n1. It is the production and emission of light by a living organism as a result of a chemical reaction.\\n2. The reaction involves the light-emitting pigment luciferin and the enzyme luciferase.\\n3. Bioluminescent organisms are found only in marine environments and never on land.\\n\\nWhich of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Bioluminescence occurs when luciferin is oxidized in the presence of luciferase enzymes.</p><p><b>Statement 3 is incorrect:</b> Terrestrial bioluminescent organisms exist, such as fireflies, glow-worms, and bioluminescent fungi.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":50,"q":"With reference to the 'Right to Fair Compensation and Transparency in Land Acquisition, Rehabilitation and Resettlement Act, 2013', consider the following statements:\\n1. It mandates conducting a Social Impact Assessment (SIA) before acquiring land for public purposes.\\n2. It mandates the consent of at least 80% of affected families for land acquisition for private companies.\\n3. It mandates the consent of at least 70% of affected families for public-private partnership (PPP) projects.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> The LARR Act, 2013 mandates Social Impact Assessments and requires prior consent of 80% of affected families for private company acquisitions and 70% for Public-Private Partnership (PPP) projects.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":51,"q":"With reference to 'Water Credit', consider the following statements:\\n1. It puts microfinance tools to work in the water and sanitation sector.\\n2. It is a global initiative launched under the aegis of the World Health Organization and the World Bank.\\n3. It aims to enable the poor people to meet their water needs without depending on subsidies.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 3 are correct:</b> WaterCredit applies microfinance principles to enable low-income households to access small, affordable loans for water connections and household toilets without relying entirely on state subsidies.</p><p><b>Statement 2 is incorrect:</b> WaterCredit was created and spearheaded by the international NGO <b>Water.org</b> (co-founded by Gary White and Matt Damon), not under the aegis of the WHO or World Bank.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":52,"q":"Consider the following statements regarding the 'Indian National Rupee' exchange rate:\\n1. Nominal Effective Exchange Rate (NEER) is a weighted average of bilateral exchange rates of the home currency relative to currencies of major trading partners.\\n2. Real Effective Exchange Rate (REER) is calculated by adjusting NEER for relative inflation differentials.\\n3. An increasing trend in REER indicates an appreciation in the country's trade competitiveness.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> NEER is the trade-weighted geometric average of exchange rates against a currency basket, while REER adjusts NEER for relative domestic vs. foreign consumer/wholesale price inflation differentials.</p><p><b>Statement 3 is incorrect:</b> A rising/increasing trend in REER signifies real currency overvaluation and a <b>loss</b> (decline) in export trade price competitiveness, not an appreciation in competitiveness.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":53,"q":"With reference to the 'Urban Cooperative Banks' (UCBs) in India, consider the following statements:\\n1. They are supervised and regulated by local boards set up by the State Governments.\\n2. They can issue equity shares and preference shares.\\n3. They were brought under the supervisory oversight of the Reserve Bank of India through the Banking Regulation (Amendment) Act, 2020.\\n\\nWhich of the statements given above are correct?","options":["1 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 2 and 3 are correct:</b> The Banking Regulation (Amendment) Act, 2020 enhanced RBI's regulatory and supervisory powers over primary urban cooperative banks (UCBs) and permitted UCBs to raise capital through equity shares, preference shares, and unsecured debentures/bonds.</p><p><b>Statement 1 is incorrect:</b> Core banking supervision and licensing are vested in the <b>Reserve Bank of India</b>, not local state government boards.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":54,"q":"Consider the following statements regarding the 'Indian Government Bond Yields':\\n1. Actions of the United States Federal Reserve influence Indian bond yields.\\n2. Actions of the Reserve Bank of India influence Indian bond yields.\\n3. Inflation and short-term interest rates determine Indian bond yields.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 only","3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three factors influence Indian sovereign bond yields:</b></p><ul><li>US Fed interest rate adjustments drive foreign portfolio debt capital flows and cross-border yield differentials.</li><li>RBI's policy repo rates, CRR tweaks, and Open Market Operations (OMOs) regulate domestic banking system liquidity.</li><li>Domestic CPI inflation dynamics and prevailing money market interest rates directly dictate fixed-income discount yields.</li></ul><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":55,"q":"Consider the following:\\n1. Foreign currency convertible bonds\\n2. Foreign institutional investment with certain conditions\\n3. Global depository receipts\\n4. Non-resident external deposits\\n\\nWhich of the above can be included in 'Foreign Direct Investment'?","options":["1, 2 and 3","3 only","2 and 4","1 and 4"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>1, 2 and 3 are treated as components eligible for FDI capital routes:</b> Foreign Currency Convertible Bonds (FCCBs), American/Global Depository Receipts (ADRs/GDRs), and institutional holdings fulfilling prescribed statutory ownership thresholds $(\\\\ge 10\\\\%)$ are categorized as FDI flows.</p><p><b>Non-Resident External (NRE) deposits</b> are banking external debt liabilities, not direct equity investment.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":56,"q":"Consider the following statements in respect of the 'Global Ocean Commission':\\n1. It is an international initiative that addresses the degradation of the ocean and the depletion of its resources.\\n2. It was established under the United Nations Convention on the Law of the Sea (UNCLOS).\\n3. It focuses on the high seas beyond national exclusive economic zones.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 3 are correct:</b> The Global Ocean Commission was an independent international body (2013–2016) created to formulate policy recommendations to address governance failures, overfishing, and ecological degradation in the High Seas (international waters beyond EEZs).</p><p><b>Statement 2 is incorrect:</b> It was an independent civil society initiative hosted by the Pew Charitable Trusts and Somerville College, Oxford, not an official treaty body created under UNCLOS.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":57,"q":"With reference to the Indian economy, consider the following statements regarding the 'Lender of Last Resort' function of the Central Bank:\\n1. Lending to trade and industry bodies when they fail to borrow from other sources.\\n2. Providing liquidity to banks facing temporary financial stress and liquidity crunches.\\n3. Guaranteeing the total debt obligations of insolvent non-banking financial entities.\\n\\nWhich of the statements given above is/are correct?","options":["1 and 2 only","2 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statement 2 is correct:</b> As the Lender of Last Resort (LOLR), the central bank (RBI) provides emergency liquidity facilities to solvent commercial banks undergoing sudden liquidity run crises when alternative inter-bank funding markets freeze.</p><p><b>Statements 1 and 3 are incorrect:</b> The central bank does not lend directly to commercial industrial corporations nor does it guarantee the bad debts of insolvent private NBFCs.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":58,"q":"Consider the following statements regarding the 'R2 Code of Practices':\\n1. It provides an environmental certification standard for electronics recyclers and refurbishers.\\n2. It prohibits the illegal export of toxic electronic waste to developing countries.\\n3. It is administered by the Basel Action Network as a mandatory statutory treaty under UNEP.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> The R2 (Responsible Recycling) standard sets strict environmental, health, and data security benchmarks for recycling, refurbishing, and handling e-waste, preventing illegal transboundary dumping of toxic materials.</p><p><b>Statement 3 is incorrect:</b> The R2 Standard is managed by <b>SERI (Sustainable Electronics Recycling International)</b> as an accredited voluntary industry standard, not a statutory treaty administered by UNEP or BAN.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":59,"q":"With reference to the 'Eighth Schedule' of the Constitution of India, consider the following statements:\\n1. It currently contains 22 languages.\\n2. Bodo, Dogri, Maithili, and Santhali were added by the 92nd Constitutional Amendment Act, 2003.\\n3. English is recognized as one of the 22 scheduled languages in the Eighth Schedule.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> The Eighth Schedule lists 22 constitutional languages. The 92nd Amendment Act (2003) inserted Bodo, Dogri, Maithili, and Santhali into the schedule.</p><p><b>Statement 3 is incorrect:</b> <b>English</b> is not included in the 22 languages listed in the Eighth Schedule of the Constitution.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":60,"q":"Consider the following statements regarding the 'T-cell Immunity':\\n1. T-cells are produced in the bone marrow and mature in the thymus.\\n2. T-cell memory allows the human immune system to respond rapidly upon reinfection by a previously encountered pathogen.\\n3. T-cells provide broad protection against intracellular viral pathogens even when circulating neutralizing antibodies decline.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> T-lymphocytes differentiate in the thymus and form long-lived memory T-cells ($CD4^+$ helper and $CD8^+$ cytotoxic cells) that recognize viral internal antigens, providing durable cellular immunity that clears infected host cells even after circulating antibody titers wane.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":61,"q":"With reference to the 'Governor of a State' in India, consider the following statements:\\n1. The Governor holds office during the pleasure of the President.\\n2. The Constitution provides specific guidelines and grounds upon which the President may remove a Governor.\\n3. The Governor has the constitutional power to reserve certain Bills passed by the State Legislature for the consideration of the President.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 3 are correct:</b> Under Article 156(1), the Governor holds office during the pleasure of the President. Under Article 200, the Governor is constitutionally empowered to reserve Bills (such as those endangering the position of the High Court) for presidential consideration under Article 201.</p><p><b>Statement 2 is incorrect:</b> The Constitution lays down <b>no grounds or guidelines</b> whatsoever for the removal of a Governor by the President.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":62,"q":"Consider the following statements regarding 'Palm Oil' production:\\n1. The African oil palm tree is native to West Africa.\\n2. Palm oil is a key raw material for the manufacturing of lipstick, soaps, and biofuel.\\n3. Indonesia and Malaysia together produce more than 80% of the world's palm oil supply.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> The oil palm <i>(Elaeis guineensis)</i> originates in West Africa. Indonesia and Malaysia dominate global production (~85%), and palm oil derivatives are ubiquitous in food processing, cosmetics, detergents, and biodiesel production.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":63,"q":"With reference to the 'Indus Valley Civilization', consider the following pairs of sites and unique archaeological findings:\\n\\n{{ <table class='table table-bordered text-center' style='width:100%; border: 1px solid #dee2e6;'><thead><tr style='background-color:#f8f9fa;'><th>Harappan Site</th><th>Archaeological Evidence</th></tr></thead><tbody><tr><td>1. Dholavira</td><td>Giant water reservoir system and stone inscriptions</td></tr><tr><td>2. Kalibangan</td><td>Ploughed field surface showing furrow marks</td></tr><tr><td>3. Lothal</td><td>Burnt-brick tidal dockyard connected to river basin</td></tr></tbody></table> }}\\n\\nWhich of the pairs given above are correctly matched?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three pairs are correctly matched:</b></p><ul><li><b>Dholavira:</b> Monumental stone-cut water reservoirs and a 10-character signboard inscription.</li><li><b>Kalibangan:</b> Pre-Harappan/Harappan ploughed agricultural field with grid furrows.</li><li><b>Lothal:</b> Basin dockyard engineered for handling tidal waters and maritime sea vessels.</li></ul><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":64,"q":"Consider the following statements regarding the 'Prompt Corrective Action' (PCA) framework in India:\\n1. It was introduced by the Reserve Bank of India to maintain financial stability among commercial banks.\\n2. It triggers structured corrective actions based on Capital Adequacy, Asset Quality (NPAs), and Leverage.\\n3. Regional Rural Banks (RRBs) are strictly governed under the mandatory PCA matrix of the RBI.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> RBI's PCA framework tracks risk thresholds (CRAR, Net NPA ratio, Tier-1 Leverage) to enforce remedial interventions before banks become insolvent.</p><p><b>Statement 3 is incorrect:</b> Regional Rural Banks (RRBs) and primary agricultural societies are explicitly excluded from the standard RBI PCA framework.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":65,"q":"With reference to the medieval history of India, the 'Iqta' system under the Delhi Sultanate was characterized by which of the following features?\\n1. Iqtas were revenue assignments given to military commanders (Muqtis/Iqtadars) in lieu of cash salary.\\n2. Iqta holders were responsible for maintaining law and order and furnishing troops during campaigns.\\n3. Iqtas were permanent hereditary private land grants that could not be transferred by the Sultan.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> The Iqta was an administrative revenue assignment granting the Muqti/Iqtadar the right to collect land revenue to maintain themselves, administrative costs, and their mandatory standing military contingents.</p><p><b>Statement 3 is incorrect:</b> Iqtas were non-hereditary, revocable territorial revenue assignments subject to regular transfers by the Sultan to prevent entrenched feudal power.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":66,"q":"Consider the following statements regarding the 'Indian Council of Medical Research' (ICMR):\\n1. It is the apex body in India for the formulation, coordination and promotion of biomedical research.\\n2. It is funded entirely by the Government of India through the Department of Health Research, Ministry of Health and Family Welfare.\\n3. It was originally established in 1911 as the Indian Research Fund Association (IRFA).\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> ICMR was founded in 1911 as the Indian Research Fund Association (IRFA) and redesignated as ICMR in 1949. It is the national biomedical research apex institution funded by the Department of Health Research (MoHFW).</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":67,"q":"With reference to the physical geography of India, consider the following statements regarding 'Bagar' and 'Rohi':\\n1. Bagar refers to the semi-arid transition plains situated to the west of the Aravallis in Rajasthan.\\n2. Rohi refers to fertile flood tracts formed by seasonal streams in Rajasthan.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"correct":2,"ex":"{{ <div className='space-y-2'><p><b>Both statements 1 and 2 are correct:</b> In Rajasthan regional geomorphology, <b>Rajasthan Bagar</b> is the semi-desert steppe zone between the Aravallis and the Thar desert, while <b>Rohi</b> refers to localized fertile agricultural silt-loam patches watered by short streams.</p><p><b>Correct Option is 3.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":68,"q":"Consider the following statements regarding 'CRISPR-Cas9' gene editing technology:\\n1. It utilizes a guide RNA to direct the Cas9 endonuclease enzyme to a specific target DNA sequence.\\n2. It can be used to insert, delete, or modify specific genetic sequences in living organisms.\\n3. The 2020 Nobel Prize in Chemistry was awarded to Emmanuelle Charpentier and Jennifer A. Doudna for the development of this method.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> CRISPR-Cas9 utilizes synthetic guide RNA (gRNA) matching target genomic sequences to direct the Cas9 molecular scissor enzyme to cut DNA strands, enabling site-directed genome modification. Emmanuelle Charpentier and Jennifer Doudna won the 2020 Nobel Prize in Chemistry for its discovery.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":69,"q":"With reference to ancient Indian history, the 'Uttaramerur Inscription' of the Chola king Parantaka I is of exceptional historical importance because it provides detailed information regarding:","options":["The maritime trade routes between the Chola kingdom and the Srivijaya empire","The democratic election procedure, committee system (Variyam), and disqualifications for village self-governance assemblies (Sabhas)","The metallurgical casting techniques used for Chola bronze icons","The tax assessment structure applied on overseas merchant guilds"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 2:</b> The 10th-century <b>Uttaramerur Inscriptions</b> of Chola King Parantaka I (in Kanchipuram district, Tamil Nadu) document the functioning, qualifications, secret-pot ballot voting (<i>Kudavolai</i> system), and executive committees (<i>Variyams</i>) of the autonomous Brahmanical village assembly (<i>Sabha</i>).</p></div> }}"},{"year":2021,"paper":"GS1","question":70,"q":"Consider the following statements regarding 'Hydrogen as a Clean Fuel':\\n1. It has the highest energy content per unit mass among common fuels.\\n2. Combustion of pure hydrogen in fuel cells produces only electricity, water, and heat.\\n3. Blue hydrogen is produced by electrolysis of water using pure solar and wind energy.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Hydrogen has high specific energy $(\\\\sim 120–142\\\\text{ MJ/kg})$ and electrochemical reaction in PEM fuel cells produces zero carbon emissions, yielding only water and heat.</p><p><b>Statement 3 is incorrect:</b> <b>Blue Hydrogen</b> is split from natural gas/fossil fuels via Steam Methane Reforming (SMR) paired with Carbon Capture and Storage (CCS). Hydrogen produced via renewable water electrolysis is designated as <b>Green Hydrogen</b>.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":71,"q":"With reference to the 'Money Market' in India, consider the following instruments:\\n1. Treasury Bills (T-Bills)\\n2. Commercial Paper (CP)\\n3. Certificate of Deposit (CD)\\n4. Call / Notice Money\\n\\nWhich of the above are short-term money market instruments with maturity up to one year?","options":["1, 2 and 3 only","2, 3 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All four are money market instruments:</b> T-Bills (91, 182, 364 days), Commercial Paper (short-term corporate unsecured debt up to 1 year), Certificates of Deposit (issued by banks up to 1 year), and Call/Notice Money (overnight to 14 days) are core short-term Money Market instruments.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":72,"q":"Consider the following statements regarding the 'Sundarbans Biosphere Reserve':\\n1. It contains the world's largest contiguous mangrove delta ecosystem.\\n2. It is the only mangrove habitat in the world populated by the Royal Bengal Tiger.\\n3. It was inscribed on the UNESCO World Network of Biosphere Reserves in 2001.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> Spanning the Ganga-Brahmaputra-Meghna delta, Sundarbans is the largest continuous tidal halophytic mangrove forest on Earth, the sole mangrove ecosystem hosting a tiger population, and a designated UNESCO Biosphere Reserve and Ramsar Site.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":73,"q":"With reference to the modern political organizations in pre-Independence India, who among the following founded the 'Servants of India Society' in 1905?","options":["Bal Gangadhar Tilak","Gopal Krishna Gokhale","Lala Lajpat Rai","Bipin Chandra Pal"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 2:</b> <b>Gopal Krishna Gokhale</b> founded the <b>Servants of India Society</b> in Pune in 1905 to train young Indians to dedicate their lives to public welfare, social reform, education, and secular nation-building.</p></div> }}"},{"year":2021,"paper":"GS1","question":74,"q":"Consider the following statements regarding 'Lithium' reserves and supply chains:\\n1. Lithium is a soft, silvery-white alkali metal with the lowest density among all solid elements.\\n2. The salt flats (Salars) of South America account for more than half of the world's identified lithium brine resources.\\n3. Lithium is completely non-conductive to electricity and thermal energy.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Lithium $(Z=3)$ is the lightest solid metal with high electrochemical potential, concentrated extensively in the South American 'Lithium Triangle' salt flats (Bolivia, Chile, Argentina).</p><p><b>Statement 3 is incorrect:</b> As an alkali metal, lithium is a conductor of both electricity and heat.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":75,"q":"Match the following historical battles of colonial India with the treaties that formally concluded them:\\n\\n{{ <table class='table table-bordered text-center' style='width:100%; border: 1px solid #dee2e6;'><thead><tr style='background-color:#f8f9fa;'><th>Battle / War</th><th>Concluding Treaty</th></tr></thead><tbody><tr><td>1. First Carnatic War</td><td>Treaty of Aix-la-Chapelle (1748)</td></tr><tr><td>2. Second Anglo-Mysore War</td><td>Treaty of Mangalore (1784)</td></tr><tr><td>3. First Anglo-Sikh War</td><td>Treaty of Lahore (1846)</td></tr></tbody></table> }}\\n\\nWhich of the pairs given above are correctly matched?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three pairs are correctly matched:</b></p><ul><li><b>First Carnatic War:</b> Ended with the Treaty of Aix-la-Chapelle (restoring Madras to the British).</li><li><b>Second Anglo-Mysore War:</b> Concluded by Tipu Sultan and Lord Macartney via the Treaty of Mangalore on mutual restoration of conquests.</li><li><b>First Anglo-Sikh War:</b> Ended with the Treaty of Lahore (1846) ceding Jalandhar Doab and requiring indemnity.</li></ul><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":76,"q":"With reference to the cultural history of India, consider the following pairs:\\n\\n{{ <table class='table table-bordered text-center' style='width:100%; border: 1px solid #dee2e6;'><thead><tr style='background-color:#f8f9fa;'><th>Ancient Term</th><th>Historical Connotation</th></tr></thead><tbody><tr><td>1. Paramitas</td><td>Perfections whose attainment led to the Bodhisattva path</td></tr><tr><td>2. Parivrajaka</td><td>Renunciant and wandering ascetic seeker</td></tr><tr><td>3. Upasaka</td><td>Lay follower of Buddhism</td></tr></tbody></table> }}\\n\\nWhich of the pairs given above are correctly matched?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three pairs are correctly matched:</b></p><ul><li><b>Paramitas:</b> The spiritual perfections or transcendent virtues (such as Dana, Shila, Kshanti, Prajna) cultivated by a Bodhisattva.</li><li><b>Parivrajaka:</b> A homeless wandering religious renunciant/monk common in the Sramana traditions.</li><li><b>Upasaka (male) / Upasika (female):</b> Lay devotees and householders who take refuge in the Buddha, Dhamma, and Sangha without adopting monastic vows.</li></ul><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":77,"q":"Consider the following statements regarding the 'Atmospheric Layers':\\n1. Temperature increases with height throughout the entire extent of the troposphere.\\n2. The stratosphere contains the ozone layer that absorbs incoming ultraviolet solar radiation.\\n3. The mesosphere is the coldest atmospheric layer where meteors burn up upon entering Earth's atmosphere.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 2 and 3 are correct:</b> The stratosphere contains the ozonosphere (15–35 km) that filters UV rays, leading to temperature inversion. The mesosphere (50–85 km) records minimum atmospheric temperatures (dropping down to $-90^circ\\text{C}$ to $-100^circ\\text{C}$) and creates high frictional resistance that disintegrates incoming meteoroids.</p><p><b>Statement 1 is incorrect:</b> Temperature <i>decreases</i> with altitude in the troposphere at the normal lapse rate ($sim 6.5^circ\\text{C}$ per km).</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":78,"q":"With reference to the Indian economy, consider the following statements regarding 'Demand-Pull Inflation':\\n1. An expansionary fiscal policy with high government spending can trigger demand-pull inflation.\\n2. Rapid growth in consumer credit and domestic money supply fuels demand-pull inflation.\\n3. A severe disruption in global crude oil supply chains causing production cost spikes is a classic driver of demand-pull inflation.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Demand-pull inflation occurs when aggregate demand exceeds aggregate supply ('too much money chasing too few goods'), spurred by deficit spending, stimulus packages, or low interest rates expanding consumer purchasing power.</p><p><b>Statement 3 is incorrect:</b> Supply shocks, import price surges, and rising raw material costs represent <b>Cost-Push Inflation</b>, not Demand-Pull Inflation.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":79,"q":"Consider the following statements regarding 'Bioluminescent Waves' (Sea Sparkle) observed along Indian beaches:\\n1. The phenomenon is caused by bloom densities of marine dinoflagellates such as Noctiluca scintillans.\\n2. The chemical emission of light serves as an anti-predator defense mechanism.\\n3. Noctiluca blooms are universally beneficial for marine fisheries as they supercharge dissolved oxygen in coastal waters.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Bioluminescent night displays ('Sea Sparkle') are generated by bioluminescent dinoflagellates (like <i>Noctiluca scintillans</i>) through luciferin-luciferase reactions when agitated by wave action, acting as a predator deterrent.</p><p><b>Statement 3 is incorrect:</b> Extensive <i>Noctiluca</i> blooms can form harmful algal blooms (HABs) that deplete dissolved oxygen upon bacterial decomposition and excrete high levels of ammonia, causing coastal fish die-offs and toxic dead zones.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":80,"q":"With reference to the constitutional developments in colonial India, the 'Pitt's India Act of 1784' was enacted to introduce which of the following institutional mechanisms?","options":["Establishment of the Board of Control to supervise civil, military, and revenue affairs, creating a system of dual control","Complete abolition of the East India Company's monopoly over tea trade and trade with China","Establishment of the Supreme Court of Judicature at Fort William in Calcutta","Introduction of direct open competitive examinations for the Indian Civil Services"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The <b>Pitt's India Act of 1784</b> established a system of double government: the Court of Directors managed commercial affairs, while a newly appointed six-member ministerial <b>Board of Control</b> represented the British Crown to guide and superintend all civil, military, and revenue operations.</p></div> }}"},{"year":2021,"paper":"GS1","question":81,"q":"Consider the following pairs of major global ocean currents and their thermal characteristics:\\n\\n{{ <table class='table table-bordered text-center' style='width:100%; border: 1px solid #dee2e6;'><thead><tr style='background-color:#f8f9fa;'><th>Ocean Current</th><th>Thermal Characteristic</th><th>Ocean Basin</th></tr></thead><tbody><tr><td>1. Kuroshio Current</td><td>Warm Current</td><td>North Pacific Ocean</td></tr><tr><td>2. Humboldt (Peru) Current</td><td>Cold Current</td><td>South Pacific Ocean</td></tr><tr><td>3. Agulhas Current</td><td>Cold Current</td><td>Indian Ocean</td></tr></tbody></table> }}\\n\\nWhich of the pairs given above are correctly matched?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Pairs 1 and 2 are correctly matched:</b></p><ul><li><b>Kuroshio Current:</b> Intense warm western boundary current flowing northward along Japan in the North Pacific.</li><li><b>Humboldt (Peru) Current:</b> Major cold eastern boundary current associated with coastal upwelling in the South Pacific.</li><li>Pair 3 is incorrect: The <b>Agulhas Current</b> is a classic <b>Warm Current</b> (western boundary current of the South Indian Ocean flowing south along Mozambique and South Africa), not a cold current.</li></ul><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":82,"q":"With reference to the history of ancient Indian science, consider the following statements regarding the 'Sulba Sutras':\\n1. They are part of the Kalpa Vedanga corpus dealing with the geometry of Vedic fire altars.\\n2. They contain early geometric expressions of irrational numbers and the theorem relating to the squares of sides in right-angled triangles.\\n3. They were authored during the late Gupta period as astronomical calculation manuals.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> The <i>Sulba Sutras</i> (composed by Baudhayana, Manava, Apastamba, and Katyayana) are Vedic geometric appendices to the <i>Shrauta Sutras</i> (part of the Kalpa Vedanga) detailing spatial constructions of sacrificial fire altars (Vedis) and early geometric principles.</p><p><b>Statement 3 is incorrect:</b> The Sulba Sutras date back to the late Vedic period (c. 800–500 BCE), long preceding the Gupta period.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":83,"q":"Consider the following statements regarding the 'Ramsar Convention on Wetlands':\\n1. It is an intergovernmental treaty adopted in 1971 in Ramsar, Iran, providing the framework for conservation of wetlands.\\n2. Montreux Record is a register of wetland sites on the Ramsar List where changes in ecological character have occurred, are occurring, or are likely to occur.\\n3. As of currently, Keoladeo National Park and Loktak Lake are the two Indian wetlands placed on the Montreux Record.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> The Ramsar Convention (1971) established international wetland safeguards. The Montreux Record lists Ramsar wetlands facing adverse ecological shifts due to human interference. In India, <b>Keoladeo National Park</b> (Rajasthan) and <b>Loktak Lake</b> (Manipur) remain on the Montreux Record (Chilika Lake was successfully removed following ecological restoration in 2002).</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":84,"q":"With reference to the Indian economy, consider the following statements regarding 'Fiscal Drag':\\n1. It refers to a situation where progressive income tax brackets push individuals into higher tax brackets as nominal wages increase due to inflation.\\n2. It results in an increase in government tax revenue without an explicit legislative increase in statutory tax rates.\\n3. It automatically expands aggregate consumer disposable income and stimulates economic consumption during stagflation.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> <b>Fiscal Drag</b> (bracket creep) happens under progressive taxation when price inflation elevates nominal incomes into higher marginal tax slabs, increasing the effective tax burden and government receipts without statutory tax revisions.</p><p><b>Statement 3 is incorrect:</b> Fiscal drag reduces real disposable income and dampens aggregate consumer demand, acting as a built-in fiscal restraint (drag) on economic expansion.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":85,"q":"Consider the following statements regarding 'Mangrove Forest Adaptations':\\n1. Pneumatophores are aerial breathing roots that grow vertically upward from waterlogged sediments.\\n2. Stilt roots and buttresses provide structural support and anchor the trees against high-energy tidal waves.\\n3. Mangroves are strictly glycophytic plants that cannot tolerate any salt concentrations in their root zones.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Mangroves feature lenticellate pneumatophores for gas exchange in anoxic mud and extensive prop/stilt roots (e.g., <i>Rhizophora</i>) to stabilize against tidal wave surges.</p><p><b>Statement 3 is incorrect:</b> Mangroves are specialized <b>halophytes</b> (salt-tolerant plants) possessing ultrafiltration membranes in root tissues and salt-secreting glands on leaves to thrive in saline environments.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":86,"q":"With reference to ancient Indian architectural history, the 'Chaitya' differs structurally from a 'Vihara' because:","options":["Chaitya is a place of prayer, congregational worship, and contains a stupa, while Vihara is a residential dwelling for monks.","Chaitya is built exclusively of bricks, while Vihara is carved out of solid mountain rock.","Chaitya is located strictly on river deltas, while Vihara is found only in desert oases.","Chaitya is dedicated to Hindu deities, while Vihara is dedicated to Jain Tirthankaras."],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> In rock-cut and structural Buddhist architecture (such as at Karle, Bhaja, and Ajanta), a <b>Chaitya-griha</b> is an apsidal hall with a vaulted barrel roof and a votive stupa used for congregational meditation and worship, whereas a <b>Vihara</b> consists of a central hall surrounded by small cells serving as monastic residences.</p></div> }}"},{"year":2021,"paper":"GS1","question":87,"q":"Consider the following statements regarding the 'Intergovernmental Panel on Climate Change' (IPCC):\\n1. It was established in 1988 by the World Meteorological Organization (WMO) and the United Nations Environment Programme (UNEP).\\n2. The IPCC conducts its own original laboratory research and field monitoring of atmospheric greenhouse gases.\\n3. It prepares comprehensive Assessment Reports evaluating the scientific basis of climate change, its impacts, and options for adaptation and mitigation.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 3 are correct:</b> The IPCC was created in 1988 by UNEP and WMO to provide policymakers with regular scientific assessments regarding climate change, future risks, and adaptation/mitigation pathways.</p><p><b>Statement 2 is incorrect:</b> The IPCC does <i>not</i> conduct original empirical laboratory research or monitor climate parameters directly; it systematically assesses and synthesizes peer-reviewed global scientific literature published by worldwide research institutions.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":88,"q":"With reference to the agrarian history of British India, the 'Tinkathia System' in Champaran (Bihar) mandated peasant cultivators to do which of the following?","options":["Cultivate indigo on 3/20th parts of their total landholding for European planters","Surrender 3/10th of their total annual grain harvest as feudal cesses (Abwabs)","Provide free unpaid labor (Begar) for three months every year on government roadworks","Pay triple land revenue in the event of continuous monsoon failure"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> Under the exploitative <b>Tinkathia System</b> enforced by European indigo planters in Champaran (Bihar), tenant farmers were legally bound to cultivate indigo on $3/20^{\\\\text{th}}$ (3 out of every 20 <i>Kathas</i>) of their best arable agricultural holdings, prompting Gandhiji's first civil disobedience experiment in India (Champaran Satyagraha, 1917).</p></div> }}"},{"year":2021,"paper":"GS1","question":89,"q":"Consider the following statements regarding 'Thermal Stratification' in temperate freshwater lakes:\\n1. Epilimnion is the warm, less dense upper layer of water in summer.\\n2. Thermocline is the intermediate transition layer characterized by a rapid vertical decrease in water temperature.\\n3. Hypolimnion is the deep, cold, and dense bottom layer that remains shielded from surface wind mixing.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> Limnological thermal stratification in lakes divides into:</p><ul><li><b>Epilimnion:</b> Top sunlit, warm, oxygenated layer.</li><li><b>Thermocline (Metalimnion):</b> Middle zone showing sharp thermal gradient $(\\\\Delta T / \\\\Delta z)$.</li><li><b>Hypolimnion:</b> Cold, dense bottom layer with uniform temperature around $4^\\\\circ\\text{C}$.</li></ul><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":90,"q":"With reference to the ancient history of India, the 'Sohgaura Copper Plate Inscription' found in Gorakhpur district (Uttar Pradesh) is historically significant because it contains:","options":["A royal Mauryan decree detailing relief measures and state granary grain distributions during a famine","A commercial contract establishing maritime trade routes between India and Rome","A military alliance treaty between the Nandas and Alexander the Great","A poetic eulogy (Prashasti) describing the Ashvamedha sacrifice performed by Pushyamitra Shunga"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The <b>Sohgaura Copper Plate</b> (c. 3rd century BCE, written in Prakrit in Ashokan Brahmi script) contains a royal administrative order specifying state storage and relief distribution of food grains from twin storehouses/granaries (<i>Koshthagara</i>) to combat agricultural drought and famine.</p></div> }}"},{"year":2021,"paper":"GS1","question":91,"q":"Consider the following statements regarding the 'Indian Council of Forestry Research and Education' (ICFRE):\\n1. It is an autonomous body under the Ministry of Environment, Forest and Climate Change.\\n2. Its headquarters is located in Dehradun, Uttarakhand.\\n3. It is responsible for overseeing and coordinating forestry research, extension, and higher forestry education in India.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> ICFRE is an autonomous apex council under the MoEFCC, headquartered at the Forest Research Institute (FRI) campus in Dehradun, directing holistic national forestry research, silviculture, and conservation education programs across regional institutes.</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":92,"q":"With reference to the constitutional history of India, the 'Radcliffe Line' drawn in August 1947 was demarcated to serve as the international boundary between which territories?","options":["India and Pakistan (demarcating the borders of Punjab and Bengal)","India and China along the McMahon line in Arunachal Pradesh","India and Afghanistan along the Durand Line","India and Myanmar along the Patkai Range"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The <b>Radcliffe Line</b> was the boundary demarcation line between the Indian and Pakistani portions of the Punjab and Bengal provinces, drawn under the chairmanship of Sir Cyril Radcliffe (Boundary Commissions) pursuant to the Indian Independence Act, 1947.</p></div> }}"},{"year":2021,"paper":"GS1","question":93,"q":"Consider the following statements regarding 'Oceanic Upwelling':\\n1. It is a process in which deep, cold, nutrient-rich water rises toward the ocean surface.\\n2. Ekman transport driven by coastal winds blowing parallel to the coastline facilitates coastal upwelling.\\n3. Major upwelling regions along the western margins of continents sustain high primary productivity and rich commercial fisheries.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":3,"ex":"{{ <div className='space-y-2'><p><b>All three statements are correct:</b> Coastal upwelling occurs when alongshore winds combine with Coriolis deflection (Ekman transport) to push warm surface water offshore, allowing cold, nitrate- and phosphate-rich sub-surface water to rise, fueling phytoplankton blooms and world-class fisheries (e.g., Peru, California, Canary, Benguela ecosystems).</p><p><b>Correct Option is 4.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":94,"q":"With reference to the ancient philosophical systems of India, which of the following schools of thought propounded the 'Atomistic Theory' (Paramanu vada) asserting that the physical universe is composed of indivisible eternal atoms?","options":["Vaisheshika","Samkhya","Mimamsa","Vedanta"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The <b>Vaisheshika school</b> of classical Indian philosophy, founded by Sage <b>Kanada</b> (Uluka), propounded the foundational atomistic metaphysics (<i>Paramanu-vada</i>), stating that all material substances in the cosmos are aggregations of indestructible, indivisible elementary atoms of earth, water, fire, and air.</p></div> }}"},{"year":2021,"paper":"GS1","question":95,"q":"Consider the following statements regarding 'Bioleaching' (Biomining) technology:\\n1. It is a process that uses microorganisms to extract valuable metals from their ores or mineral concentrates.\\n2. Chemolithotrophic bacteria like Acidithiobacillus ferrooxidans are commonly used in the bioleaching of copper and gold ores.\\n3. Bioleaching requires operating temperatures above $1,200^\\\\circ\\text{C}$ and generates large volumes of toxic sulfur dioxide gas emissions.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Bioleaching leverages acidophilic iron- and sulfur-oxidizing bacteria (such as <i>Acidithiobacillus ferrooxidans</i>) to oxidize insoluble metal sulfides into water-soluble sulfates at ambient/moderate temperatures.</p><p><b>Statement 3 is incorrect:</b> Bioleaching is a biological wet-hydrometallurgical process operating under mild ambient temperatures, avoiding high-temperature roasting ($>1,000^\\\\circ\\text{C}$) and completely eliminating $SO_2$ gas emissions associated with traditional pyrometallurgical smelting.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":96,"q":"With reference to the economic reforms during the Delhi Sultanate, the 'Market Control Regulations' fixing prices of grains, cloth, horses, and slaves were instituted by which Sultan?","options":["Alauddin Khalji","Ghiyasuddin Balban","Muhammad bin Tughlaq","Sikandar Lodi"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> <b>Alauddin Khalji</b> instituted comprehensive market control and price-fixation regulations overseen by the <i>Shahna-i-Mandi</i> and <i>Diwan-i-Riyasat</i>, setting ceiling prices on all essential commodities in Delhi to maintain a large standing army at low cost without escalating state wage expenditures.</p></div> }}"},{"year":2021,"paper":"GS1","question":97,"q":"Consider the following statements regarding 'Ocean Acidification':\\n1. It is caused by the absorption of atmospheric carbon dioxide $(CO_2)$ by seawater.\\n2. It decreases the pH and the saturation state of calcium carbonate $(\\\\text{CaCO}_3)$ minerals in the ocean.\\n3. It enhances the ability of shell-forming marine organisms like corals, pteropods, and mollusks to construct their skeletal structures.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> Anthropogenic $CO_2$ dissolves in oceans forming carbonic acid $(H_2CO_3)$, increasing hydrogen ion concentration (lowering pH) and reacting with carbonate ions $(CO_3^{2-})$ to form bicarbonate.</p><p><b>Statement 3 is incorrect:</b> The reduction in available free carbonate ions hinders and impairs (rather than enhances) calcification in corals, mollusks, and calcifying plankton, weakening their shells and exoskeletons.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":98,"q":"With reference to modern Indian history, consider the following statements regarding the 'Indian National Trade Union Congress' (INTUC):\\n1. It was established in May 1947 with Sardar Vallabhbhai Patel presiding over its inaugural conference.\\n2. It adopted the principle of Gandhian non-violence and arbitration for resolving industrial labor disputes.\\n3. It was formed as the labor wing of the Communist Party of India.\\n\\nWhich of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"correct":1,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> INTUC was founded in May 1947 by Indian National Congress leaders (inaugurated under Sardar Patel's presidency) to champion labor rights through Gandhian principles of arbitration, conciliation, and social justice.</p><p><b>Statement 3 is incorrect:</b> INTUC was affiliated with the <b>Indian National Congress</b>, whereas the All India Trade Union Congress (AITUC) became the labor wing associated with the Communist Party of India.</p><p><b>Correct Option is 2.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":99,"q":"Consider the following statements regarding 'Equatorial Low-Pressure Belt' (Doldrums):\\n1. It is a thermal low-pressure zone located along the equator extending between $5^\\\\circ\\\\text{N}$ and $5^\\\\circ\\\\text{S}$ latitudes.\\n2. Intense solar heating causes strong vertical convection currents, resulting in calm horizontal surface winds and daily afternoon convectional thunderstorms.\\n3. Strong horizontal gale-force Coriolis winds blow continuously across this belt throughout the year.\\n\\nWhich of the statements given above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Statements 1 and 2 are correct:</b> The Equatorial Low (Doldrums) is a thermally induced low-pressure belt characterized by intense surface insolation, strong ascending vertical air convection, high humidity, cumulonimbus formations, and light, sluggish surface breezes.</p><p><b>Statement 3 is incorrect:</b> The Coriolis force is virtually <b>zero at the equator</b>, resulting in an absence of strong geostrophic winds or horizontal cyclonic shear at the surface.</p><p><b>Correct Option is 1.</b></p></div> }}"},{"year":2021,"paper":"GS1","question":100,"q":"With reference to the ancient architectural history of India, the famous 'Rathas' (Monolithic Rock-Cut Chariot Temples) at Mahabalipuram (Mamallapuram) were excavated during the reign of which Pallava ruler?","options":["Narasimhavarman I (Mamalla)","Mahendravarman I","Nandivarman II","Simhavishnu"],"correct":0,"ex":"{{ <div className='space-y-2'><p><b>Correct Option is 1:</b> The monolithic rock-cut <b>Pancha Rathas</b> (Dharmaraja, Bhima, Arjuna, Nakula-Sahadeva, and Draupadi Rathas) at Mahabalipuram were carved out of single granite boulders in the 7th century CE during the reign of the Pallava monarch <b>Narasimhavarman I</b> (surnamed <i>Mamalla</i>).</p></div> }}"}]`);export{e as default};